#include "sbas_signal_replica.h"
#include "gps_sdr_signal_replica.h"
#include <array>
#include <cmath>


void sbas_l1_code_gen_complex_sampled(own::span<std::complex<float>> dest, uint32_t prn, int32_t sampling_freq)
{
    constexpr int32_t code_chip_rate = 1023000;
    constexpr int32_t code_length = 1023;

    const float ts = 1.0F / static_cast<float>(sampling_freq);
    const float tc = 1.0F / static_cast<float>(code_chip_rate);

    std::array<std::complex<float>, code_length> code_aux{};
    sbas_l1_code_gen_complex(code_aux, prn, 0U);

    const auto samples_per_code = static_cast<int32_t>(dest.size());
    for (int32_t i = 0; i < samples_per_code; i++)
        {
            const auto idx = static_cast<int32_t>(std::floor(ts * static_cast<float>(i) / tc));
            if (i == samples_per_code - 1)
                {
                    dest[i] = code_aux[code_length - 1];
                }
            else
                {
                    dest[i] = code_aux[idx];
                }
        }
}


void sbas_l1_code_gen_float(own::span<float> dest, uint32_t prn)
{
    gps_l1_ca_code_gen_float(dest, static_cast<int32_t>(prn), 0U);
}


void sbas_l1_code_gen_complex(own::span<std::complex<float>> dest, uint32_t prn, uint32_t chip_shift)
{
    constexpr uint32_t code_length = 1023;
    std::array<int32_t, code_length> ca_code_int{};
    gps_l1_ca_code_gen_int(ca_code_int, static_cast<int32_t>(prn), chip_shift);
    for (uint32_t ii = 0; ii < code_length; ++ii)
        {
            dest[ii] = {static_cast<float>(ca_code_int[ii]), 0.0F};
        }
}
